import { z } from 'zod';
import { timestampSchema } from './sync';

/** A comment's text: a BlockNote document, text only, as a task's description. */
export const commentBodySchema = z.array(z.record(z.string(), z.unknown())).min(1);
export type CommentBody = z.infer<typeof commentBodySchema>;

/**
 * A comment on a task (docs/data-model.md). Comments are not part of the activity log, but are
 * shown with it in the task's timeline, ordered by `createdAt` and then `id`.
 */
export const commentSchema = z.object({
  /** UUIDv7 generated by the client, so a comment can be written offline. */
  id: z.uuid(),
  workspaceId: z.uuid(),
  projectId: z.uuid(),
  taskId: z.uuid(),
  /** The author, set by the server. Null once their account is deleted. */
  userId: z.string().nullable(),
  body: commentBodySchema,
  /**
   * When the server received the comment. Null on the device until a comment written there
   * syncs, which places it after everything the server has dated.
   */
  createdAt: timestampSchema.nullable(),
  /** When the body was last edited; null until it is. A placeholder until the edit syncs. */
  editedAt: timestampSchema.nullable(),
});
export type Comment = z.infer<typeof commentSchema>;

/** Writing a comment. The server sets the workspace, project and author from the task. */
export const createCommentSchema = commentSchema
  .pick({ id: true, taskId: true, body: true })
  .strict();
export type CreateComment = z.infer<typeof createCommentSchema>;

/** Editing a comment, applied in the order edits reach the server. */
export const updateCommentSchema = commentSchema.pick({ body: true }).strict();
export type UpdateComment = z.infer<typeof updateCommentSchema>;
